import numpy as np

def planted_in_top(pairs):
    """Number of (i, i + 1) pairs with i even and i < 40."""
    return sum(1 for i, j in pairs if j == i + 1 and i % 2 == 0 and i < 40)


def split_means(results, break_day=1512):
    """Monthly means of cycles whose trading ends by break_day,
    and of cycles whose trading starts on it or later."""
    before = [r for s, r in results if s + 378 <= break_day]
    after = [r for s, r in results if s + 252 >= break_day]
    return float(np.mean(before)) / 6, float(np.mean(after)) / 6

import numpy as np

def convergence_share(close, start, k, wait=0):
    Pn = normalise(close[start:start + 378])
